import { useMemo } from 'react';

import { useAuthenticationService } from 'admin-portal-shared-services';
import { featureToggles } from 'config/featureToggle';
import { useFeatureToggle } from 'hooks';
import { hasConnectScope, hasViewerScope } from 'utils';

interface ConnectSectionAccess {
  showGenomePortalCard: boolean;
  isConnectAppFullWidth: boolean;
}

const CONNECT_INFLUENCER_TOGGLE_ID =
  featureToggles.pillar.connectionsAndCreativity.submenus.connectInfluencer.id;

export const useConnectSectionAccess = (): ConnectSectionAccess => {
  const authenticationService = useAuthenticationService();
  const scopes = authenticationService.getUserScopes();

  const [isConnectInfluencerEnabled, isToggleLoading] = useFeatureToggle(
    CONNECT_INFLUENCER_TOGGLE_ID,
  );

  return useMemo(() => {
    const hasViewerAccess = hasViewerScope(scopes);
    const hasConnectAccess = hasConnectScope(scopes);

    const showGenomePortalCard =
      !isToggleLoading &&
      isConnectInfluencerEnabled === true &&
      hasViewerAccess &&
      hasConnectAccess;

    return {
      showGenomePortalCard,
      isConnectAppFullWidth: !showGenomePortalCard,
    };
  }, [scopes, isConnectInfluencerEnabled, isToggleLoading]);
};
